def hflip(grid):
    """Mirror the grid left to right."""
    return [r[::-1] for r in grid]

def vflip(grid):
    """Mirror the grid top to bottom."""
    return grid[::-1]

def hmirror_double(grid):
    """Each row followed by its own left-right mirror."""
    return [row + row[::-1] for row in grid]

def flip_sandwich(grid, flip=True):
    """Stack vflip(grid), grid, vflip(grid); if flip, mirror each grid row first."""
    x = hflip(grid) if flip else grid
    return x[::-1] + x + x[::-1]

